+                    if (
+                        maxOrMin == null ||
+                        itemValue
+                            .minus(valueObject)
+                            .abs()
+                            .isLessThanOrEqual(maxOrMin.minus(valueObject).abs())
+                            .getValue() === true
+                    ) {
+                        maxOrMin = itemValue;
+                        maxOrMinPosition = { row, column };
+                    }
+                }
+            }
+        };
+
+        if (isDesc) {
