+        const columnCount = this._columnCount;
+
+        const result: BaseValueObject[][] = [];
+
+        for (let r = 0; r < rowCount; r++) {
+            const rowList: BaseValueObject[] = [];
+            for (let c = 0; c < columnCount; c++) {
+                const currentValue = this._values?.[r]?.[c];
