+                                currentValue = new StringValueObject(rowValue);
+                            } else if (typeof rowValue === 'number') {
+                                currentValue = new NumberValueObject(rowValue);
+                            } else if (typeof rowValue === 'boolean') {
+                                currentValue = new BooleanValueObject(rowValue);
+                            }
